inline void ClientImpl::stop() {
  std::lock_guard<std::mutex> guard(socket_mutex_);
  if (socket_requests_in_flight_ > 0) {
    shutdown_socket(socket_);
    socket_should_be_closed_when_request_is_done_ = true;
    return;
  }
  disconnect( true);
}
